// =============================================================================
// Module: rom_ahb
// Project: 1TOPS RISC-V System-on-Chip
// Purpose: Synthesizable On-Chip Boot ROM with AHB-Lite Slave Interface.
//          The ROM contents are a case table (synthesizable for ASIC and FPGA).
//          The table between the BOOTROM TABLE BEGIN/END markers below is
//          GENERATED by software/gen_bootrom.py from the internal boot ROM
//          program (software/bootrom_int + software/common/loader.S):
//              make -C software rom
//          Do not edit the table by hand.
//
//          Current table: generated by gen_bootrom.py from bootrom_int.elf
//          (88 words, 352 of 4096 bytes): the SPI "BOOT"-stream
//          loader (software/bootrom_int/bootrom_int.S + software/common/loader.S).
//          See rpi4_spi_boot_options.txt and changes_s1.md for the boot flow.
// =============================================================================

// `timescale 1ns / 1ps

module rom_ahb #(
    parameter XLEN        = 32,
    parameter PA_BITS     = 32,
    parameter ADDR_RANGE  = 4095,      // 4 KB aperture (1024 words)
    parameter PRELOAD     = 0,
    parameter        MEMFILE = ""
)(
    input  logic                 HCLK,
    input  logic                 HRESETn,
    input  logic                 HSELRom,
    // spyglass disable_block W240
    // SMD: Input declared but not read
    // SJ: HTRANS[0] unused; HADDR[31:12] decoded by interconnect; HADDR[1:0] unused (word aligned)
    input  logic [PA_BITS-1:0]   HADDR,
    input  logic                 HREADY,
    input  logic [1:0]           HTRANS,
    // spyglass enable_block W240
    output logic [XLEN-1:0]      HREADRom,
    output logic                 HRESPRom,
    output logic                 HREADYRom
);

    localparam WORDS      = (ADDR_RANGE + 1) / (XLEN / 8);
    localparam ADDR_WIDTH = (WORDS > 1) ? $clog2(WORDS) : 1;
    localparam OFFSET     = $clog2(XLEN / 8);

    // Single-cycle zero-wait synchronous ROM response
    assign HREADYRom = 1'b1;
    assign HRESPRom  = 1'b0;

    // spyglass disable_block W528
    // SMD: Variable set but not read
    // SJ: Explicitly consume unread port bits to prevent W240 SignalUsageReport warning
    wire unused_ok = &{1'b0, HADDR[31:12], HADDR[1:0], HTRANS[0], 1'b0};
    // spyglass enable_block W528

    wire [ADDR_WIDTH-1:0] word_addr = HADDR[ADDR_WIDTH+OFFSET-1:OFFSET];

    // Synthesizable combinational ROM lookup function
    function automatic [XLEN-1:0] rom_data(input logic [ADDR_WIDTH-1:0] addr);
        case (addr)
            // -----------------------------------------------------------------
            // Dual-Mode Bootloader Program Image
            // -----------------------------------------------------------------
            // >>> BOOTROM TABLE BEGIN (generated by software/gen_bootrom.py; do not edit by hand)
            10'd0:  rom_data = 32'h8001_8137; // 0x1000: lui sp,0x80018
            10'd1:  rom_data = 32'h0080_00ef; // 0x1004: jal 100c <spi_init>
            10'd2:  rom_data = 32'h0b80_006f; // 0x1008: j 10c0 <load_image>
            10'd3:  rom_data = 32'h1004_02b7; // 0x100c: lui t0,0x10040
            10'd4:  rom_data = 32'h0630_0313; // 0x1010: li t1,99
            10'd5:  rom_data = 32'h0062_a023; // 0x1014: sw t1,0(t0) # 10040000 <SPI_BASE>
            10'd6:  rom_data = 32'h0030_0313; // 0x1018: li t1,3
            10'd7:  rom_data = 32'h0062_a223; // 0x101c: sw t1,4(t0)
            10'd8:  rom_data = 32'h0002_a823; // 0x1020: sw zero,16(t0)
            10'd9:  rom_data = 32'h00f0_0313; // 0x1024: li t1,15
            10'd10: rom_data = 32'h0062_aa23; // 0x1028: sw t1,20(t0)
            10'd11: rom_data = 32'h0002_ac23; // 0x102c: sw zero,24(t0)
            10'd12: rom_data = 32'h0008_0337; // 0x1030: lui t1,0x80
            10'd13: rom_data = 32'h0462_a023; // 0x1034: sw t1,64(t0)
            10'd14: rom_data = 32'h0402_aa23; // 0x1038: sw zero,84(t0)
            10'd15: rom_data = 32'h04c2_a303; // 0x103c: lw t1,76(t0)
            10'd16: rom_data = 32'hfe03_5ee3; // 0x1040: bgez t1,103c <spi_init+0x30>
            10'd17: rom_data = 32'h0000_8067; // 0x1044: ret
            10'd18: rom_data = 32'h1004_02b7; // 0x1048: lui t0,0x10040
            10'd19: rom_data = 32'h0020_0313; // 0x104c: li t1,2
            10'd20: rom_data = 32'h0062_ac23; // 0x1050: sw t1,24(t0) # 10040018 <SPI_BASE+0x18>
            10'd21: rom_data = 32'h0000_8067; // 0x1054: ret
            10'd22: rom_data = 32'h1004_02b7; // 0x1058: lui t0,0x10040
            10'd23: rom_data = 32'h0000_0313; // 0x105c: li t1,0
            10'd24: rom_data = 32'h0062_ac23; // 0x1060: sw t1,24(t0) # 10040018 <SPI_BASE+0x18>
            10'd25: rom_data = 32'h0000_8067; // 0x1064: ret
            10'd26: rom_data = 32'h1004_02b7; // 0x1068: lui t0,0x10040
            10'd27: rom_data = 32'h0482_a303; // 0x106c: lw t1,72(t0) # 10040048 <SPI_BASE+0x48>
            10'd28: rom_data = 32'hfe03_4ee3; // 0x1070: bltz t1,106c <spi_read_byte+0x4>
            10'd29: rom_data = 32'h0402_a423; // 0x1074: sw zero,72(t0)
            10'd30: rom_data = 32'h0742_a303; // 0x1078: lw t1,116(t0)
            10'd31: rom_data = 32'h0023_7313; // 0x107c: andi t1,t1,2
            10'd32: rom_data = 32'hfe03_0ce3; // 0x1080: beqz t1,1078 <spi_read_byte+0x10>
            10'd33: rom_data = 32'h04c2_a503; // 0x1084: lw a0,76(t0)
            10'd34: rom_data = 32'hfe05_4ee3; // 0x1088: bltz a0,1084 <spi_read_byte+0x1c>
            10'd35: rom_data = 32'h0ff5_7513; // 0x108c: zext.b a0,a0
            10'd36: rom_data = 32'h0000_8067; // 0x1090: ret
            10'd37: rom_data = 32'h0000_8f93; // 0x1094: mv t6,ra
            10'd38: rom_data = 32'h0000_0e13; // 0x1098: li t3,0
            10'd39: rom_data = 32'h0000_0e93; // 0x109c: li t4,0
            10'd40: rom_data = 32'h0200_0f13; // 0x10a0: li t5,32
            10'd41: rom_data = 32'hfc5f_f0ef; // 0x10a4: jal 1068 <spi_read_byte>
            10'd42: rom_data = 32'h01d5_1533; // 0x10a8: sll a0,a0,t4
            10'd43: rom_data = 32'h00ae_6e33; // 0x10ac: or t3,t3,a0
            10'd44: rom_data = 32'h008e_8e93; // 0x10b0: addi t4,t4,8
            10'd45: rom_data = 32'hffee_98e3; // 0x10b4: bne t4,t5,10a4 <spi_read_word+0x10>
            10'd46: rom_data = 32'h000e_0513; // 0x10b8: mv a0,t3
            10'd47: rom_data = 32'h000f_8067; // 0x10bc: jr t6
            10'd48: rom_data = 32'hf89f_f0ef; // 0x10c0: jal 1048 <spi_cs_low>
            10'd49: rom_data = 32'hfd1f_f0ef; // 0x10c4: jal 1094 <spi_read_word>
            10'd50: rom_data = 32'h544f_52b7; // 0x10c8: lui t0,0x544f5
            10'd51: rom_data = 32'hf422_8293; // 0x10cc: addi t0,t0,-190 # 544f4f42 <MAGIC>
            10'd52: rom_data = 32'h0655_1863; // 0x10d0: bne a0,t0,1140 <err_magic>
            10'd53: rom_data = 32'hfc1f_f0ef; // 0x10d4: jal 1094 <spi_read_word>
            10'd54: rom_data = 32'h0005_0413; // 0x10d8: mv s0,a0
            10'd55: rom_data = 32'hfb9f_f0ef; // 0x10dc: jal 1094 <spi_read_word>
            10'd56: rom_data = 32'h0005_0493; // 0x10e0: mv s1,a0
            10'd57: rom_data = 32'h0404_8a63; // 0x10e4: beqz s1,1138 <done>
            10'd58: rom_data = 32'h0000_82b7; // 0x10e8: lui t0,0x8
            10'd59: rom_data = 32'h0492_ee63; // 0x10ec: bltu t0,s1,1148 <err_addr>
            10'd60: rom_data = 32'h0094_0333; // 0x10f0: add t1,s0,s1
            10'd61: rom_data = 32'h8000_02b7; // 0x10f4: lui t0,0x80000
            10'd62: rom_data = 32'h0454_6863; // 0x10f8: bltu s0,t0,1148 <err_addr>
            10'd63: rom_data = 32'h8000_82b7; // 0x10fc: lui t0,0x80008
            10'd64: rom_data = 32'h0054_7663; // 0x1100: bgeu s0,t0,110c <chk_dmem>
            10'd65: rom_data = 32'h0462_e263; // 0x1104: bltu t0,t1,1148 <err_addr>
            10'd66: rom_data = 32'h0180_006f; // 0x1108: j 1120 <copy>
            10'd67: rom_data = 32'h8001_02b7; // 0x110c: lui t0,0x80010
            10'd68: rom_data = 32'h0254_6c63; // 0x1110: bltu s0,t0,1148 <err_addr>
            10'd69: rom_data = 32'h8001_82b7; // 0x1114: lui t0,0x80018
            10'd70: rom_data = 32'h0254_7863; // 0x1118: bgeu s0,t0,1148 <err_addr>
            10'd71: rom_data = 32'h0262_e663; // 0x111c: bltu t0,t1,1148 <err_addr>
            10'd72: rom_data = 32'hf49f_f0ef; // 0x1120: jal 1068 <spi_read_byte>
            10'd73: rom_data = 32'h00a4_0023; // 0x1124: sb a0,0(s0)
            10'd74: rom_data = 32'h0014_0413; // 0x1128: addi s0,s0,1
            10'd75: rom_data = 32'hfff4_8493; // 0x112c: addi s1,s1,-1
            10'd76: rom_data = 32'hfe04_98e3; // 0x1130: bnez s1,1120 <copy>
            10'd77: rom_data = 32'hfa1f_f06f; // 0x1134: j 10d4 <next_chunk>
            10'd78: rom_data = 32'hf21f_f0ef; // 0x1138: jal 1058 <spi_cs_high>
            10'd79: rom_data = 32'h0004_0067; // 0x113c: jr s0
            10'd80: rom_data = 32'h0e10_0393; // 0x1140: li t2,225
            10'd81: rom_data = 32'h0080_006f; // 0x1144: j 114c <err>
            10'd82: rom_data = 32'h0e20_0393; // 0x1148: li t2,226
            10'd83: rom_data = 32'hf0df_f0ef; // 0x114c: jal 1058 <spi_cs_high>
            10'd84: rom_data = 32'h8001_82b7; // 0x1150: lui t0,0x80018
            10'd85: rom_data = 32'hffc2_8293; // 0x1154: addi t0,t0,-4 # 80017ffc <ERR_ADDR>
            10'd86: rom_data = 32'h0072_a023; // 0x1158: sw t2,0(t0)
            10'd87: rom_data = 32'h0000_006f; // 0x115c: j 115c <err+0x10>
            // <<< BOOTROM TABLE END
            default: rom_data = 32'h0000_0013; // Default NOP
        endcase
    endfunction

`ifndef SYNTHESIS
    // Optional custom preload override for simulation
    logic [XLEN-1:0] mem [0:WORDS-1];
    initial begin
        if (PRELOAD && MEMFILE != "") begin
            $readmemh(MEMFILE, mem);
        end
    end
    wire [XLEN-1:0] rom_read_word = (PRELOAD && MEMFILE != "") ? mem[word_addr] : rom_data(word_addr);
`else
    wire [XLEN-1:0] rom_read_word = rom_data(word_addr);
`endif

    always_ff @(posedge HCLK or negedge HRESETn) begin
        if (!HRESETn) begin
            HREADRom <= '0;
        end else if (HSELRom && HREADY && HTRANS[1]) begin
            HREADRom <= rom_read_word;
        end
    end

endmodule
